"""Generic patient-level cohort table for round-2 runs (Schurch now; tier1 cohorts later by config only).

Cohort config (JSON):
{
  "name": "schurch",
  "adapter": "schurch" | "table",
  # adapter "table" (tier1 and future cohorts):
  "table": "/path/cells.(parquet|csv|npz)", "patient_col": "patient", "label_col": "label",
  "label_map": {"raw label": "17-node name" | null}  or  "label_map_file": "/path/map.json",
  "marker_columns": {"raw column": "vocabulary name", ...},
  "transform": "log1p" | "arcsinh:<cofactor>" | "none",
  # common:
  "panel_bank": "/path/bank.json" (generated by make_bank() if absent, BEFORE any result),
  (string values may use ${ADMIT_RUNS}, ${ADMIT_DATA_ROOT} and ${ADMIT_REPO}; see load_config)
  "splits": {"seeds": [0, ..., 19], "n_train": 15, "n_cal": 12, "n_test": 8}
            (or {"seeds": [...], "fractions": [15, 12, 8]} -> patient counts scaled to the cohort),
  "train_cap": 2000, "heads": ["logistic", "xgb"]
}
Labels must end up in the 17-node space; rows whose label maps to null are excluded and counted.
"""
from __future__ import annotations

import json
import os
import sys
from datetime import datetime
from pathlib import Path

import numpy as np
import pandas as pd

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from common import REPO, RUNS, write_json  # noqa: E402


def load_config(path) -> dict:
    """Read a cohort config JSON; ${ADMIT_RUNS}, ${ADMIT_DATA_ROOT} and ${ADMIT_REPO} in string values are
    replaced by the output root, the data root and the repository root."""
    roots = {"ADMIT_RUNS": str(RUNS), "ADMIT_DATA_ROOT": os.environ.get("ADMIT_DATA_ROOT", str(REPO / "data")),
             "ADMIT_REPO": str(REPO)}

    def ex(v):
        if isinstance(v, str):
            for k, r in roots.items():
                v = v.replace("${" + k + "}", r)
            return v
        if isinstance(v, dict):
            return {k: ex(x) for k, x in v.items()}
        if isinstance(v, list):
            return [ex(x) for x in v]
        return v
    return ex(json.loads(Path(path).read_text()))

R_MARKERS = ["CD45", "CD20", "CD3e", "CD8", "CD4", "FOXP3", "CD68", "CD163", "CD11c", "HLADR", "CD31", "PanCK",
             "aSMA", "CD56", "CD15", "CD138"]
ISOFORMS = ["CD45RO", "CD45RA"]
GROUPS = [["CD8"], ["CD4"], ["FOXP3"], ["CD20"], ["CD68"], ["CD163"], ["PanCK", "Ecadherin"], ["CD31"], ["aSMA"],
          ["CD45"]]
EXT_GROUPS = [["CD45", "CD45RO", "CD45RA"], ["CD3e", "CD4", "CD8", "FOXP3"]]


def load_cohort_table(cfg: dict) -> dict:
    if cfg.get("adapter") == "schurch":
        from schurch_common import load_schurch
        d = load_schurch()
        return {"x": d["x"], "markers": d["markers"], "label_name": d["label_name"], "patient": d["patient"],
                "excluded": d["excluded"], "transform": "log1p (pilot)"}
    path = Path(cfg["table"])
    if path.suffix == ".parquet":
        df = pd.read_parquet(path)
    elif path.suffix == ".npz":
        z = np.load(path, allow_pickle=True)
        df = pd.DataFrame({k: z[k] for k in z.files if z[k].ndim == 1})
    else:
        df = pd.read_csv(path, low_memory=False)
    lm = cfg.get("label_map") or json.loads(Path(cfg["label_map_file"]).read_text())
    lab = df[cfg["label_col"]].astype(str).map(lambda v: lm.get(v))
    excluded = df.loc[lab.isna(), cfg["label_col"]].astype(str).value_counts().to_dict()
    keep = lab.notna().to_numpy()
    cols = list(cfg["marker_columns"].keys())
    x = df.loc[keep, cols].to_numpy(dtype=np.float64)
    tr = cfg.get("transform", "log1p")
    if tr == "log1p":
        x = np.log1p(np.clip(x, 0, None))
    elif tr.startswith("arcsinh"):
        x = np.arcsinh(x / float(tr.split(":")[1]))
    return {"x": x, "markers": [cfg["marker_columns"][c] for c in cols], "label_name": lab[keep].to_numpy(),
            "patient": df.loc[keep, cfg["patient_col"]].astype(str).to_numpy(), "excluded": excluded,
            "transform": tr}


def make_bank(full, out: Path) -> dict:
    """Round-1 Schurch-bank logic for any cohort panel. Refuses to overwrite (the bank is fixed)."""
    if out.exists():
        return json.loads(out.read_text())
    bank = []

    def add(name, family, keep, note=""):
        keep = [m for m in full if m in set(keep)]
        bank.append({"name": name, "family": family, "markers": keep,
                     "deleted": [m for m in full if m not in keep], "n_markers": len(keep),
                     **({"note": note} if note else {})})

    add("full", "full", full)
    for m in R_MARKERS + ISOFORMS:
        if m in full:
            add(f"del_{m}", "single", [x for x in full if x != m])
    for g in GROUPS:
        gg = [m for m in g if m in full]
        if gg:
            add("grp_" + "+".join(gg), "lineage_group", [x for x in full if x not in gg])
    for g in EXT_GROUPS:
        gg = [m for m in g if m in full]
        if len(gg) > 1:
            add("grp_" + "+".join(gg), "lineage_group_extension", [x for x in full if x not in gg])
    for seed in range(5):
        perm = np.random.default_rng(seed).permutation(len(full))
        for f in (0.75, 0.50, 0.25):
            k = int(round(f * len(full)))
            add(f"rand{int(f * 100)}_s{seed}", "random_retention", [full[i] for i in sorted(perm[:k])])
    obj = {"created": datetime.now().isoformat(timespec="seconds"), "full_panel": list(full),
           "n_panels": len(bank), "panels": bank}
    write_json(out, obj)
    return obj


def make_splits(patient: np.ndarray, spec: dict):
    ids = np.unique(patient)
    if "n_train" in spec:
        n_tr, n_ca, n_te = spec["n_train"], spec["n_cal"], spec["n_test"]
    else:
        f = np.array(spec.get("fractions", [15, 12, 8]), dtype=float)
        n_tr, n_ca = (np.floor(f[:2] / f.sum() * len(ids))).astype(int)
        n_te = len(ids) - n_tr - n_ca
    assert n_tr + n_ca + n_te <= len(ids)
    out = []
    for seed in spec["seeds"]:
        rng = np.random.default_rng(seed)
        perm = rng.permutation(ids)
        out.append({"seed": int(seed), "rng": rng, "train": perm[:n_tr], "cal": perm[n_tr:n_tr + n_ca],
                    "test": perm[n_tr + n_ca:n_tr + n_ca + n_te]})
    return out
